                    nxt[r][c] = 1
                else:
                    nxt[r][c] = 0
        cur = nxt

    total: int = 0
    for row in cur:
        row_sum: int = 0
        for val in row:
            row_sum = row_sum + val
        total = total + row_sum
    return total

